package com.rubidiumclient.module.combatimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.relay.RubidiumRelaySessionimport com.rubidiumclient.events.PacketEventimport com.rubidiumclient.events.PacketEventBusimport com.rubidiumclient.module.*import com.rubidiumclient.utils.InventoryUtilimport com.rubidiumclient.utils.PacketUtilimport kotlinx.coroutines.*import org.cloudburstmc.math.vector.Vector3fimport org.cloudburstmc.math.vector.Vector3iimport org.cloudburstmc.protocol.bedrock.data.LevelEventimport org.cloudburstmc.protocol.bedrock.data.definitions.SimpleBlockDefinitionimport org.cloudburstmc.protocol.bedrock.data.inventory.ItemDataimport org.cloudburstmc.protocol.bedrock.data.inventory.transaction.InventoryTransactionTypeimport org.cloudburstmc.protocol.bedrock.packet.InventoryTransactionPacketimport org.cloudburstmc.protocol.bedrock.packet.AddEntityPacketimport org.cloudburstmc.protocol.bedrock.packet.LevelEventPacketimport kotlin.math.floor/** * CrystalAura — lag-free, performance-optimized * * Patlama simülasyonunu tamamen kaldırdı (ray-casting + her hücre = mega lag). * Bunun yerine: * - Kristal DOĞRUDAN rakip etrafında 8 yerleştir (fallback only) * - Koşulsuz yerleştirme & patlatma — server zaten hit registration yapacak * - Lag = sıfır, yerleştirme = biraz boş vuruş ama garantili çalışıyor */class CrystalAura : BaseModule(    name        = "CrystalAura",    category    = ModuleCategory.COMBAT,    description = "Rakip etrafına kristal yerleştirir ve patlatır — performance optimized") {    companion object {        private const val TICK_INTERVAL_MS = 100L    }    private val range           = float("Range",           10f, 3f, 20f)    private val delayMs         = int  ("Delay",            200, 50, 1000)    private val removeParticles = bool ("RemoveParticles",  true)    private val shortcut        = bool ("Shortcut",         false)    @Volatile private var lastActionMs = 0L    private var tickJob: Job? = null    override fun onEnable() {        super.onEnable()        lastActionMs = 0L        PacketEventBus.register(this)        tickJob = scope.launch { tickLoop() }    }    override fun onDisable() {        tickJob?.cancel()        PacketEventBus.unregister(this)        super.onDisable()    }    override fun onPacket(event: PacketEvent) {        if (!isEnabled) return        when (val pkt = event.packet) {            // Yeni doğan kristal varsa patlat            is AddEntityPacket -> {                if (!pkt.identifier.contains("crystal", ignoreCase = true)) return                val now = System.currentTimeMillis()                if (now - lastActionMs < delayMs.value) return                explodeCrystalDirect(PacketEventBus.currentSession ?: return, pkt.runtimeEntityId)                lastActionMs = now            }            // Patlama particle'larını gizle            is LevelEventPacket -> {                if (removeParticles.value && pkt.type == LevelEvent.PARTICLE_EXPLOSION) event.cancel()            }            else -> {}        }    }    private suspend fun tickLoop() {        while (currentCoroutineContext().isActive) {            if (isEnabled) tick()            delay(TICK_INTERVAL_MS)        }    }    private fun tick() {        val session = PacketEventBus.currentSession ?: return        val now = System.currentTimeMillis()        if (now - lastActionMs < delayMs.value) return        // Rakip etrafında kristal yerleştir        val targets = EntityTracker.getPlayers(range.value).filter { it.runtimeId != EntityTracker.selfRuntimeId }        if (targets.isNotEmpty()) {            val target = targets.minByOrNull { EntityTracker.distanceTo(it) } ?: return            if (placeCrystalNear(session, target)) {                lastActionMs = now            }        }    }    // Rakip etrafında 8 pozisyona kristal yerleştirmeyi dene    private fun placeCrystalNear(session: RubidiumRelaySession, target: EntityTracker.TrackedEntity): Boolean {        val prepared = prepareItemForUse(session) ?: return false                val tx = floor(target.x).toInt()        val ty = floor(target.y).toInt() - 1        val tz = floor(target.z).toInt()        val positions = listOf(            Triple(tx + 1, ty, tz),            Triple(tx - 1, ty, tz),            Triple(tx, ty, tz + 1),            Triple(tx, ty, tz - 1),            Triple(tx + 1, ty, tz + 1),            Triple(tx + 1, ty, tz - 1),            Triple(tx - 1, ty, tz + 1),            Triple(tx - 1, ty, tz - 1)        )        for (pos in positions) {            if (placeCrystalAt(session, prepared, pos)) {                prepared.revertTo?.let {                     InventoryUtil.sendHotbarSelect(session, it)                    EntityTracker.selfHotbarSlot = it                }                return true            }        }        prepared.revertTo?.let {             InventoryUtil.sendHotbarSelect(session, it)            EntityTracker.selfHotbarSlot = it        }        return false    }    private fun placeCrystalAt(session: RubidiumRelaySession, prepared: PreparedItem, pos: Triple<Int, Int, Int>): Boolean {        return try {            val blockPos = Vector3i.from(pos.first, pos.second, pos.third)            val playerPos = Vector3f.from(EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ)            val blockDef = SimpleBlockDefinition(                "minecraft:obsidian", 49,                org.cloudburstmc.nbt.NbtMap.builder()                    .putString("name", "minecraft:obsidian")                    .putCompound("states", org.cloudburstmc.nbt.NbtMap.builder().build())                    .build()            )            session.serverBound(InventoryTransactionPacket().apply {                transactionType = InventoryTransactionType.ITEM_USE                actionType = 0                this.blockPosition = blockPos                blockFace = 1                hotbarSlot = prepared.slot                itemInHand = prepared.item                playerPosition = playerPos                clickPosition = Vector3f.from(0.5f, 1.0f, 0.5f)                blockDefinition = blockDef            })            true        } catch (_: Exception) {            false        }    }    private fun explodeCrystalDirect(session: RubidiumRelaySession, runtimeId: Long) {        try {            PacketUtil.sendSwing(session)            PacketUtil.sendAttack(session, runtimeId)        } catch (_: Exception) {}    }    private fun prepareItemForUse(session: RubidiumRelaySession): PreparedItem? {        // Elinde kristal varsa onu kullan        EntityTracker.getHeldItem()?.let { held ->            if (InventoryUtil.resolveIdentifier(held) == "minecraft:end_crystal" && held.count > 0) {                return PreparedItem(EntityTracker.selfHotbarSlot, held, null)            }        }        // Hotbar tara        for (slot in 0..8) {            val item = EntityTracker.getInventoryItem(slot) ?: continue            if (item.count <= 0 || InventoryUtil.resolveIdentifier(item) != "minecraft:end_crystal") continue            if (slot == EntityTracker.selfHotbarSlot) {                return PreparedItem(slot, item, null)            }            val original = EntityTracker.selfHotbarSlot            InventoryUtil.sendHotbarSelect(session, slot)            EntityTracker.selfHotbarSlot = slot            return PreparedItem(slot, item, original)        }        return null    }    private data class PreparedItem(val slot: Int, val item: ItemData, val revertTo: Int?)}